import { FieldItem } from '@t/GridField';
import { ViewCellRenderer } from '@/renderer/ViewCellRenderer';
import { GridMain } from '@/view/GridMain';
import { CellInfo, Config } from '@t/GridConfig';
import { GridOptions } from '@/types/GridOptions';
import { RefImgValue } from '@/types/RefValue';
/**
 * image renderer
 *
 * @class ImageRenderer
 * @typedef {ImageRenderer}
 * @extends {ViewCellRenderer}
 */
export class ImageRenderer extends ViewCellRenderer {
  constructor(field: FieldItem, gridMain: GridMain) {
    super(field, gridMain);
  }

  public render(cellInfo: CellInfo, element: HTMLElement): void {
    const item = cellInfo.item;
    const value = this.getValue(item);
    const refValue = this.getRefValue(value, item) as RefImgValue;
    const labelText = refValue?.label ?? null;
    const src = refValue?.src ?? value;
    const alt = refValue?.alt ?? '';

    // 캐싱된 요소 재사용
    let img = element.querySelector('img.dg-cell-content') as HTMLImageElement;
    let label = element.querySelector('span.dg-cell-content-label') as HTMLSpanElement;

    // img 없으면 새로 생성
    if (!img) {
      img = document.createElement('img');
      img.className = 'dg-cell-content';
      element.appendChild(img);
    }

    // 이미지 속성 변경이 필요한 경우만 변경
    if (img.src !== src) img.src = src;
    if (alt && img.alt !== alt) img.alt = alt;

    // label이 필요한 경우
    if (labelText) {
      if (!label) {
        label = document.createElement('span');
        label.className = 'dg-cell-content-label';
        element.appendChild(label);
      }

      if (label.textContent !== labelText) {
        label.textContent = labelText;

        this.tooltip(element, labelText);
      }
    } else if (label) {
      // 필요 없는 label은 제거
      label.remove();
      this.tooltip(element, '');
    }
  }

  public getMinWidth(cfg: Config, opts: GridOptions) {
    return 60;
  }
}
